template<typename T>
void print_type(T value) {
    if constexpr (std::is_integral_v<T>) {
        std::cout << "Integral: " << value << '\n';
    } else if constexpr (std::is_floating_point_v<T>) {
        std::cout << "Float: " << value << '\n';
    } else {
        std::cout << "Other\n";
    }
}
// Неиспользуемые ветки отбрасываются на этапе компиляции

enum class Color { Red, Green, Blue };

void process(Color c) {
    switch (c) {
        case Color::Red:
            std::cout << "Red\n";
            break;  // без break — fallthrough!
        case Color::Green:
            std::cout << "Green\n";
            break;
        case Color::Blue:
            std::cout << "Blue\n";
            break;
        default:
            std::cout << "Unknown\n";
    }
}

