switch (x) {
    case 1:
        do_something();
        [[fallthrough]];  // намеренный fallthrough, подавляет warning
    case 2:
        do_other();
        break;
}

while (true) {
    auto input = get_input();
    if (input == "quit") break;
    process(input);
}

// Тело выполняется ХОТЯ БЫ ОДИН РАЗ
std::string input;
do {
    std::cout << "Enter command: ";
    std::cin >> input;
    process(input);
} while (input != "exit");

