// Область видимости i ограничена циклом (C++11)

std::vector<int> v = {1, 2, 3, 4, 5};

// По значению (копия — для простых типов)
for (int x : v) {
    std::cout << x << ' ';
}

// По ссылке (модификация элементов)
for (int& x : v) {
    x *= 2;
}

// По const ссылке (чтение без копии — для больших объектов)
for (const auto& x : v) {
    std::cout << x << ' ';
}

// С инициализатором (C++20)
for (auto vec = get_vector(); const auto& x : vec) {
    // vec живёт только в цикле
}

int arr[] = {1, 2, 3};
for (int x : arr) { ... }

std::map<int, std::string> m;
for (const auto& [key, value] : m) {  // structured bindings (C++17)
    std::cout << key << ": " << value << '\n';
}

for (int i = 0; i < 100; ++i) {
    if (found(i)) {
